function listing(c){
 const items=DATA.entries.filter(i=>i[0]===c.id);
 return '<main id="main-content" class="site-container listing-main"><div class="back-row"><a href="/">→ بازگشت به خانه</a><span class="english-label">'+c.english+'</span></div><header class="page-heading glass-panel"><div class="eyebrow" dir="ltr">BIOGLASS ARCHIVE / '+c.index+'</div><h1>'+c.title+'</h1><p>'+c.desc+'</p><div class="archive-status"><span class="pulse-dot"></span> در حال آماده‌سازی محتوا و اَسِت‌ها</div></header><div class="listing-heading">'+sectionTitle('STRUCTURE PREVIEW','چیدمان نمونه‌ها','این موارد فقط برای نمایش قالب ساخته شده‌اند؛ فایل، مقاله یا تصویر واقعی هنوز بارگذاری نشده است.')+'</div><div class="portfolio-grid">'+items.map(card).join('')+'</div><aside class="empty-notice glass-panel"><span>+</span><div><strong>آماده افزودن محتوای واقعی</strong><p>پس از آماده شدن مقاله‌ها، ارائه‌ها و تصاویر، نمونه‌ها با محتوای تأییدشده جایگزین می‌شوند.</p></div><a href="/about">درباره پروژه ↖</a></aside></main>';
}
function detail(i,c){
 const list=i[6].map((v,n)=>'<li><span dir="ltr">0'+(n+1)+'</span>'+escapeHTML(v)+'</li>').join('');
 return '<main id="main-content" class="site-container detail-main"><div class="back-row"><a href="/'+c.id+'">→ بازگشت به '+c.title+'</a><span class="english-label">STRUCTURE PREVIEW</span></div><div class="detail-grid"><article class="detail-content glass-panel"><div class="eyebrow">'+escapeHTML(i[3])+' / BIOGLASS</div><h1>'+escapeHTML(i[2])+'</h1><p class="detail-description">'+escapeHTML(i[4])+'</p><div class="demo-alert">◇ <p>این صفحه نمونه‌ی طراحی است؛ هنوز سند علمی، تصویر واقعی یا فایل دانلودی به آن متصل نشده است.</p></div><h2>ساختار پیش‌بینی‌شده</h2><ol class="detail-outline">'+list+'</ol><p class="detail-bottom-text">نسخه نهایی هر صفحه شامل اطلاعات منبع، تاریخ انتشار، پیوست‌ها و اعتبار علمی خواهد بود.</p></article><div class="detail-visual glass-panel"><div class="display-topline"><span>RESERVED / '+escapeHTML(i[5].toUpperCase())+'</span><span>+</span></div>'+placeholder(i[5])+'<div class="detail-visual-caption">محل اَسِت اختصاصی این محتوا</div></div></div></main>';
}
function about(){
 return '<main id="main-content" class="site-container about-main"><div class="about-grid"><section class="about-copy glass-panel"><div class="eyebrow" dir="ltr">ABOUT THE STUDIO</div><h1>یک دفتر باز برای <span>مسیر یادگیری.</span></h1><p>BioGlass Studio برای ثبت و نمایش مسیر علمی یک دانشجوی دندان‌پزشکی طراحی شده است؛ از ایده‌های اولیه و پروژه‌های کلاسی تا پژوهش‌ها و ارائه‌های دانشگاهی.</p><div class="about-values"><div><b style="font-size:25px;color:#45b5c5">✦</b><strong>یادگیری پیوسته</strong><span>ثبت پیشرفت و مهارت‌های علمی</span></div><div><b style="font-size:25px;color:#45b5c5">◇</b><strong>مستندسازی دقیق</strong><span>نگهداری فایل‌ها و منابع قابل ارجاع</span></div><div><b style="font-size:25px;color:#45b5c5">✳</b><strong>اشتراک مسئولانه</strong><span>رعایت حریم خصوصی و اعتبار محتوا</span></div></div><p class="about-pending">نام کامل، بیوگرافی، دانشگاه، رزومه و راه‌های تماس پس از تأیید صاحب پورتفولیو تکمیل می‌شوند.</p><a href="/projects" class="button-primary">مشاهده قالب پروژه‌ها ↖</a></section><div class="about-portrait glass-panel"><div class="display-topline"><span>PERSONAL PROFILE</span><span>01 / PENDING</span></div>'+placeholder('portrait')+'<p>جایگاه پرتره اختصاصی؛ در مرحله تولید اَسِت تعیین می‌شود.</p></div></div></main>';
}
function layout(page,title){
 return '<!doctype html><html lang="fa" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light"><meta name="theme-color" content="#eff8fb"><meta name="robots" content="noindex,nofollow"><meta name="description" content="BioGlass Studio | پورتفولیوی نمونه یک دانشجوی دندان‌پزشکی"><link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="stylesheet" href="/style.css"><title>'+escapeHTML(title)+' | BioGlass Studio</title></head><body><a href="#main-content" class="skip-link">رفتن به محتوای اصلی</a><div class="page-atmosphere" aria-hidden="true"></div>'+header()+'<div class="preview-ribbon"><b>PREVIEW / ZH3 CLOUDFLARE</b><span>نسخه آزمایشی BioGlass Studio • محتوای نمونه</span></div>'+page+footer()+(page.includes('id="bioglass-scene"')?'<script type="module" src="/scene.js"></script>':'')+'</body></html>';
}
const staticResponse=(text,type)=>new Response(text,{status:200,headers:{'content-type':type,'cache-control':'public, max-age=180','x-content-type-options':'nosniff'}});
export default {
 async fetch(request) {
  const url=new URL(request.url);
  const path=decodeURIComponent(url.pathname).replace(/\/+$/,'')||'/';
  if(path==='/style.css')return staticResponse(CSS,'text/css; charset=utf-8');
  if(path==='/scene.js')return staticResponse(THREE_SCENE,'text/javascript; charset=utf-8');
  if(path==='/favicon.svg')return staticResponse('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="18" fill="#d6f8fc"/><path d="M18 10c35 12 35 32 0 44M46 10C11 22 11 42 46 54M24 22h16M20 32h24M24 42h16" stroke="#168da2" stroke-width="4" fill="none" stroke-linecap="round"/></svg>','image/svg+xml');
  if(path==='/robots.txt')return staticResponse('User-agent: *\nDisallow: /\n','text/plain; charset=utf-8');
  if(path==='/'||path==='/index.html')return staticResponse(layout(home(),'صفحه اصلی'),'text/html; charset=utf-8');
  if(path==='/about')return staticResponse(layout(about(),'درباره استودیو'),'text/html; charset=utf-8');
  const segments=path.split('/').filter(Boolean);
  const c=DATA.collections.find(x=>x.id===segments[0]);
  if(c&&segments.length===1)return staticResponse(layout(listing(c),c.title),'text/html; charset=utf-8');
  if(c&&segments.length===2){const item=DATA.entries.find(x=>x[0]===c.id&&x[1]===segments[1]);if(item)return staticResponse(layout(detail(item,c),item[2]),'text/html; charset=utf-8');}
  return new Response(layout('<main id="main-content" class="site-container missing-main"><div class="glass-panel missing-card"><p class="eyebrow">404 / ARCHIVE NOT FOUND</p><h1>این صفحه پیدا نشد.</h1><p>ممکن است نشانی تغییر کرده باشد.</p><a href="/" class="button-primary">بازگشت به صفحه اصلی</a></div></main>','صفحه پیدا نشد'),{status:404,headers:{'content-type':'text/html; charset=utf-8','x-robots-tag':'noindex'}});
 }
};
